def _parse_scalar(value: str):
    """Parse a simple YAML scalar value."""
    if value in ("true", "True", "TRUE"):
        return True
    if value in ("false", "False", "FALSE"):
        return False
    if value in ("null", "Null", "NULL", "~", ""):
        return None
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    return value


def _parse_simple_yaml(text: str) -> dict:
    """Parse a minimal subset of YAML: nested mappings with scalar values."""
    result: dict = {}
    stack: list[tuple[dict, int]] = [(result, -1)]
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        indent = len(line) - len(line.lstrip())
        key, sep, value = stripped.partition(":")
        if not sep:
            continue
        key = key.strip()
        value = value.strip()
        while stack and indent <= stack[-1][1]:
            stack.pop()
        current = stack[-1][0]
        if value == "":
            child: dict = {}
            current[key] = child
            stack.append((child, indent))
        else:
            current[key] = _parse_scalar(value)
    return result


def load_feature_flags() -> dict:
    """Load feature flags from configs/feature_flags.yaml.

    Returns an empty dict when the file is missing so callers can fall back
    to their default behavior.
    """
    path = config_path("feature_flags.yaml")
    if not path.exists():
        return {}
    return _parse_simple_yaml(path.read_text(encoding="utf-8"))

